export interface EvalClause {
  section_number: string;
  clause_type: string;
  purpose: string;
  fairness: FairnessRating;
  market_standard: string;
  explanation: string;
}

export interface EvalSuccess {
  error: null;
  overall_fairness: FairnessRating;
  summary: string;
  call_to_action: string[];
  clauses: EvalClause[];
}

export interface EvalError {
  error: true;
  reason: string;
}

export type EvalResponse = EvalSuccess | EvalError;

export function isEvalSuccess(res: unknown): res is EvalSuccess {
  return (
    typeof res === 'object' &&
    res !== null &&
    'error' in res &&
    (res as { error: unknown }).error === null &&
    'overall_fairness' in res &&
    'clauses' in res &&
    Array.isArray((res as { clauses: unknown }).clauses) &&
    'call_to_action' in res &&
    Array.isArray((res as { call_to_action: unknown }).call_to_action)
  );
}

export function isEvalError(res: unknown): res is EvalError {
  return (
    typeof res === 'object' &&
    res !== null &&
    'error' in res &&
    (res as { error: unknown }).error === true &&
    'reason' in res
  );
}

