const Anthropic = require('@anthropic-ai/sdk');
const { readFileSync } = require('fs');
const { z } = require('zod');

// Inline the schemas since we can't import TS modules
const FairnessRatingSchema = z.enum(['fair', 'non-standard', 'dealbreaker']);
const EvalClauseSchema = z.object({
  section_number: z.string(),
  clause_type: z.string(),
  purpose: z.string(),
  fairness: FairnessRatingSchema,
  market_standard: z.string(),
  explanation: z.string(),
});
const EvalSuccessSchema = z.object({
  error: z.null(),
  overall_fairness: FairnessRatingSchema,
  summary: z.string(),
  call_to_action: z.array(z.string()),
  clauses: z.array(EvalClauseSchema),
});
const EvalErrorSchema = z.object({
  error: z.literal(true),
  reason: z.string(),
});
const EvalResponseSchema = z.discriminatedUnion('error', [EvalSuccessSchema, EvalErrorSchema]);

// Build prompt same way as system-prompt.ts
const successSchema = JSON.stringify(z.toJSONSchema(EvalSuccessSchema), null, 2);
const errorSchema = JSON.stringify(z.toJSONSchema(EvalErrorSchema), null, 2);

const SYSTEM_PROMPT = \`You are a senior in-house commercial lawyer reviewing a vendor contract on behalf of the customer. Your job is to evaluate the contract against market standards and flag every clause that deviates.

## Step 1: Determine if this is a contract

Before analyzing, determine if the input text is a contract or legal agreement. If it is clearly not a contract (e.g., a recipe, article, resume, code, or other non-legal document), return the error JSON schema below instead of the success schema.

When in doubt, treat the input as a contract and proceed with analysis. Bias toward accepting borderline input.

## Step 2: Analyze each clause

For each material clause in the contract, produce an analysis object. Write the \"purpose\" field in plain English from the customer's perspective — describe what the clause means for the customer, not what it legally governs.

## Step 3: Assign fairness tiers

For each clause, assign one of three fairness tiers:

- **fair**: Market standard or better. No action needed.
- **non-standard**: Non-standard, worth negotiating. Not a dealbreaker but the customer should push back.
- **dealbreaker**: Dealbreaker. Do not sign without resolving this clause.

## Step 4: Compute the topline

The overall_fairness is determined by the worst clause. One dealbreaker clause makes the entire contract a dealbreaker. Never average across clauses.

If more than 10% of the clauses are non-standard that is also death by paper cuts.

Write a summary sentence describing the clause breakdown.

Write a call_to_action array with prioritized, opinionated recommendations.

## Output format

Return only valid JSON matching one of the two schemas below. No text, no markdown fences — just the raw JSON object.

### Success schema
\${successSchema}

### Error schema (non-contract input)
\${errorSchema}\`;

const client = new Anthropic.default({ apiKey: process.env.ANTHROPIC_API_KEY });
const model = 'claude-haiku-4-5-20251001';

async function verify(label, text) {
  try {
    const message = await client.messages.create({
      model,
      max_tokens: 4096,
      system: SYSTEM_PROMPT,
      messages: [{ role: 'user', content: text }],
    });
    const content = message.content[0];
    if (!content || content.type !== 'text') {
      console.log('❌ ' + label + ': no text content');
      return;
    }
    let parsed;
    try { parsed = JSON.parse(content.text); } catch {
      console.log('❌ ' + label + ': invalid JSON');
      console.log('   Raw: ' + content.text.slice(0, 300));
      return;
    }
    const result = EvalResponseSchema.safeParse(parsed);
    if (!result.success) {
      console.log('❌ ' + label + ': schema validation failed');
      console.log('   Errors: ' + JSON.stringify(result.error.issues).slice(0, 400));
      console.log('   Raw keys: ' + Object.keys(parsed).join(', '));
      if (parsed.clauses && parsed.clauses[0]) console.log('   First clause fairness: ' + parsed.clauses[0].fairness);
      return;
    }
    const data = result.data;
    if (data.error === null) {
      console.log('✅ ' + label + ': overall_fairness=' + data.overall_fairness + ', clauses=' + data.clauses.length);
    } else {
      console.log('✅ ' + label + ': error — reason=\"' + data.reason + '\"');
    }
  } catch (e) {
    console.log('❌ ' + label + ': API error — ' + e.message);
  }
}

async function main() {
  console.log('Model: ' + model + '\n');
  await verify('non-contract', 'Here is my favorite chocolate chip cookie recipe: preheat oven to 375°F, mix butter and sugar...');
  const files = ['contract_1_clean', 'contract_2_egregious', 'contract_3_nonstandard', 'contract_4_minor_issues', 'contract_5_mixed'];
  for (const f of files) {
    const text = readFileSync('docs/gc-ai-takehome/' + f + '.txt', 'utf-8');
    await verify(f, text);
  }
}
main();
