const Anthropic = require('@anthropic-ai/sdk');
const { z } = require('zod');

const FairnessRatingSchema = z.enum(['fair', 'non-standard', 'dealbreaker']);
const EvalClauseSchema = z.object({ section_number: z.string(), clause_type: z.string(), purpose: z.string(), fairness: FairnessRatingSchema, market_standard: z.string(), explanation: z.string() });
const EvalSuccessSchema = z.object({ error: z.null(), overall_fairness: FairnessRatingSchema, summary: z.string(), call_to_action: z.array(z.string()), clauses: z.array(EvalClauseSchema) });
const EvalErrorSchema = z.object({ error: z.literal(true), reason: z.string() });
const EvalResponseSchema = z.discriminatedUnion('error', [EvalSuccessSchema, EvalErrorSchema]);

const client = new Anthropic.default({ apiKey: process.env.ANTHROPIC_API_KEY });
const model = 'claude-3-haiku-20240307';

const successSchema = JSON.stringify(z.toJSONSchema(EvalSuccessSchema), null, 2);
const errorSchema = JSON.stringify(z.toJSONSchema(EvalErrorSchema), null, 2);

const SYSTEM_PROMPT = 'You are a senior in-house commercial lawyer reviewing a vendor contract on behalf of the customer. Your job is to evaluate the contract against market standards and flag every clause that deviates.\n\n## Step 1: Determine if this is a contract\n\nBefore analyzing, determine if the input text is a contract or legal agreement. If it is clearly not a contract (e.g., a recipe, article, resume, code, or other non-legal document), return the error JSON schema below instead of the success schema.\n\nWhen in doubt, treat the input as a contract and proceed with analysis. Bias toward accepting borderline input.\n\n## Step 2: Analyze each clause\n\nFor each material clause in the contract, produce an analysis object. Write the \"purpose\" field in plain English from the customer perspective — describe what the clause means for the customer, not what it legally governs.\n\n## Step 3: Assign fairness tiers\n\nFor each clause, assign one of three fairness tiers:\n\n- **fair**: Market standard or better for this type of agreement. No action needed.\n- **non-standard**: Deviates from market standard in a way that disadvantages the customer, but is not a showstopper on its own. Worth negotiating. Examples: shorter-than-typical notice periods, above-market late fees, narrow warranty scope.\n- **dealbreaker**: A clause that creates unacceptable risk or fundamentally shifts the balance of power. Do not sign without resolving. Examples: vendor can unilaterally amend terms, no IP indemnification, liability cap under 6 months of fees, no data export on termination, linking to external terms that can change without consent. A non-standard clause can also be a dealbreaker if it heightens structural risk.\n\n## Step 4: Compute the topline\n\nThe overall_fairness is determined by the worst clause. One dealbreaker clause makes the entire contract a dealbreaker. Never average across clauses.\n\nDeath by paper cuts: if more than 30% of material clauses are non-standard, escalate the overall rating to dealbreaker even if no single clause qualifies on its own — the cumulative risk is too high.\n\nWrite a summary sentence describing the clause breakdown.\n\nWrite a call_to_action array with prioritized, opinionated recommendations. Lead with dealbreakers, then negotiating points, then acceptable items. Each entry should reference the section number and clause type.\n\n## Output format\n\nReturn only valid JSON matching one of the two schemas below. No text, no markdown fences — just the raw JSON object.\n\n### Success schema\n' + successSchema + '\n\n### Error schema (non-contract input)\n' + errorSchema;

function stripFences(text) { return text.replace(/^\`\`\`(?:json)?\s*\n?/,'').replace(/\n?\`\`\`\s*$/,''); }

const simpleContract = 'SERVICE AGREEMENT\n\n1. Term: This agreement is for 12 months starting January 1, 2025.\n2. Payment: Customer shall pay Vendor \$500/month, due on the 1st.\n3. Termination: Either party may terminate with 30 days written notice.\n4. Liability: Vendor liability is capped at fees paid in the prior 12 months.';
const nonContract = 'Here is my favorite chocolate chip cookie recipe: preheat oven to 375F, mix butter and sugar...';

async function verify(label, text) {
  const start = Date.now();
  try {
    const msg = await client.messages.create({ model, max_tokens: 4096, system: SYSTEM_PROMPT, messages: [{ role: 'user', content: text }] });
    const ttft = Date.now() - start;
    if (msg.stop_reason === 'max_tokens') { console.log('FAIL ' + label + ': truncated'); return; }
    const c = msg.content[0];
    if (!c || c.type !== 'text') { console.log('FAIL ' + label + ': no text content'); return; }
    const raw = stripFences(c.text.trim());
    let parsed;
    try { parsed = JSON.parse(raw); } catch { console.log('FAIL ' + label + ': invalid JSON — ' + raw.slice(0,200)); return; }
    const r = EvalResponseSchema.safeParse(parsed);
    if (!r.success) {
      console.log('FAIL ' + label + ': schema fail — ' + JSON.stringify(r.error.issues).slice(0,400));
      return;
    }
    if (r.data.error === null) {
      const tiers = r.data.clauses.reduce((a,c) => { a[c.fairness]=(a[c.fairness]||0)+1; return a; }, {});
      console.log('PASS ' + label + ': overall=' + r.data.overall_fairness + ' clauses=' + r.data.clauses.length + ' ' + JSON.stringify(tiers) + ' ttft=' + ttft + 'ms');
    } else {
      console.log('PASS ' + label + ': error — ' + r.data.reason + ' ttft=' + ttft + 'ms');
    }
  } catch (e) { console.log('FAIL ' + label + ': ' + e.message); }
}

async function main() {
  console.log('Model: ' + model);
  await verify('non-contract', nonContract);
  await verify('simple-contract', simpleContract);
}
main();
