'use client';

import { useState } from 'react';
import { FileDropZone } from './FileDropZone';
import { getFileExtension } from './validation';

async function evaluateContract(file: File) {
  const text = await file.text();
  const res = await fetch('/api/evaluate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text }),
  });
  return res.json();
}

function LoadingShimmer() {
  return (
    <div data-testid="loading-shimmer" className="space-y-4">
      <div className="h-6 w-3/4 animate-pulse rounded bg-foreground/10" />
      <div className="h-4 w-full animate-pulse rounded bg-foreground/10" />
      <div className="h-4 w-5/6 animate-pulse rounded bg-foreground/10" />
      <div className="h-4 w-2/3 animate-pulse rounded bg-foreground/10" />
      <div className="h-20 w-full animate-pulse rounded bg-foreground/10" />
    </div>
  );
}

export default function EvaluateContractPage() {
  const [file, setFile] = useState<File | null>(null);
  const [instructions, setInstructions] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  async function handleSubmit() {
    if (!file) return;
    setIsLoading(true);
    try {
      await evaluateContract(file);
    } finally {
      setIsLoading(false);
      setFile(null);
      setInstructions('');
    }
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6 px-4 py-12">
      <h1 className="text-3xl font-bold tracking-tight">Evaluate Contract</h1>
      {isLoading ? (
        <LoadingShimmer />
      ) : (
        <>
          <FileDropZone file={file} onFileChange={setFile} />
          <textarea
            value={instructions}
            onChange={(e) => setInstructions(e.target.value)}
            placeholder="Add any specific instructions for the evaluation..."
            rows={4}
            className="w-full rounded-lg border border-foreground/20 bg-transparent px-4 py-3 text-sm placeholder:text-foreground/40 focus:border-foreground/40 focus:outline-none"
          />
        </>
      )}
      <button
        type="button"
        disabled={!file || isLoading}
        onClick={handleSubmit}
        className="rounded-lg bg-foreground px-6 py-3 text-sm font-medium text-background disabled:opacity-40"
      >
        Evaluate Contract
      </button>
    </div>
  );
}
```

