'use client';

import { useState } from 'react';
import { FileDropZone } from './FileDropZone';

async function evaluateContract(file: File, instructions: string) {
  const text = await file.text();
  const res = await fetch('/api/evaluate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text, instructions }),
  });
  if (!res.ok) throw new Error('evaluation failed');
  return res.json();
}

function ShimmerBar({ className }: { className: string }) {
  return <div className={`animate-pulse rounded bg-foreground/[0.06] ${className}`} />;
}

function LoadingShimmer() {
  return (
    <div data-testid="loading-shimmer" className="space-y-6">
      {/* Fairness badge + summary */}
      <div className="space-y-3">
        <ShimmerBar className="h-8 w-28 rounded-full" />
        <ShimmerBar className="h-4 w-full" />
        <ShimmerBar className="h-4 w-4/5" />
      </div>

      {/* Call to action */}
      <div className="space-y-2 border-l-2 border-foreground/[0.06] pl-4">
        <ShimmerBar className="h-3.5 w-3/4" />
        <ShimmerBar className="h-3.5 w-2/3" />
      </div>

      {/* Clause cards */}
      {[1, 2, 3].map((i) => (
        <div
          key={i}
          className="space-y-2.5 rounded-lg border border-foreground/[0.06] p-4"
          style={{ animationDelay: `${i * 150}ms` }}
        >
          <div className="flex items-center gap-3">
            <ShimmerBar className="h-5 w-14" />
            <ShimmerBar className="h-5 w-32" />
            <ShimmerBar className="ml-auto h-5 w-20 rounded-full" />
          </div>
          <ShimmerBar className="h-3.5 w-full" />
          <ShimmerBar className="h-3.5 w-5/6" />
        </div>
      ))}
    </div>
  );
}

export default function EvaluateContractPage() {
  const [file, setFile] = useState<File | null>(null);
  const [instructions, setInstructions] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  async function handleSubmit() {
    if (!file) return;
    setIsLoading(true);
    try {
      await evaluateContract(file, instructions);
    } finally {
      setIsLoading(false);
      setFile(null);
      setInstructions('');
    }
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6 px-4 py-12">
      <h1 className="text-3xl font-bold tracking-tight">Evaluate Contract</h1>

      {isLoading ? (
        <LoadingShimmer />
      ) : (
        <>
          <FileDropZone file={file} onFileChange={setFile} />

          <textarea
            value={instructions}
            onChange={(e) => setInstructions(e.target.value)}
            placeholder="Add any specific instructions for the evaluation..."
            rows={4}
            className="w-full rounded-lg border border-foreground/20 bg-transparent px-4 py-3 text-sm placeholder:text-foreground/40 focus:border-foreground/40 focus:outline-none"
          />
        </>
      )}

      <button
        type="button"
        disabled={!file || isLoading}
        onClick={handleSubmit}
        className="rounded-lg bg-foreground px-6 py-3 text-sm font-medium text-background disabled:opacity-40"
      >
        Evaluate Contract
      </button>
    </div>
  );
}

