  });
  if (!res.ok) throw new Error('evaluation failed');
  return res.json();
}

function ShimmerBar({ h, w, pill }: { h: string; w: string; pill?: boolean }) {
  return (
    <div
      className={`animate-pulse bg-foreground/[0.06] h-${h} w-${w} ${pill ? 'rounded-full' : 'rounded'}`}
