}
```

**The submit handler:**

```typescript
  async function handleSubmit() {
    if (!file) return;
    setIsLoading(true);
    try {
      await evaluateContract(file, instructions);
      setFile(null);
      setInstructions('');
    } catch {
      // error-display step will handle this
    } finally {
      setIsLoading(false);
    }
  }
```

**The render swap + accessibility:**

```typescript
      <p className="sr-only" role="status">
        {isLoading ? 'Evaluating contract, please wait...' : ''}
      </p>

      {isLoading ? (
        <LoadingShimmer />
